int read_index_entry(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    git_index_entry *entry;
    size_t entry_size;

    if (buffer_size < sizeof(git_index_entry)) {
        return -1;
    }

    entry = (git_index_entry *)malloc(buffer_size);
    if (!entry) {
        return -1;
    }

    memcpy(entry, buffer, buffer_size);
    entry_size = buffer_size;

    if (entry->flags & GIT_INDEX_ENTRY_VALID) {
        if (entry->flags & GIT_INDEX_ENTRY_COMPRESSED) {
            size_t path_length = strlen(last) + strlen(entry->path) + 1;
            char *full_path = (char *)malloc(path_length);
            if (!full_path) {
                free(entry);
                return -1;
            }

            snprintf(full_path, path_length, "%s/%s", last, entry->path);
            free(entry->path);
            entry->path = full_path;
        }
    } else {
        free(entry);
        return -1;
    }

    *out = entry;
    *out_size = entry_size;

    return 0;
}

